// Ground-plane radials for a monopole: `count` rods spread evenly around `center`.
const args = {
  center:   { type: "point",  default: [0, 0, 0], label: "Feed point" },
  count:    { type: "int",    default: 4, min: 3, max: 32, label: "Radials" },
  length:   { type: "length", default: 31, label: "Radial length" },
  droop:    { type: "angle",  default: 0, min: 0, max: 60, label: "Droop (°)" },
  radius:   { type: "length", default: 1, label: "Rod radius" },
  material: { type: "material" },
};

function generate(a) {
  const tilt = a.droop * Math.PI / 180;
  return Array.from({ length: a.count }, (_, i) => {
    const phi = 2 * Math.PI * i / a.count;
    const r = a.length * Math.cos(tilt);
    return {
      name: `radial${i + 1}`,
      shape: "cylinder",
      start: a.center,
      stop: [a.center[0] + r * Math.cos(phi), a.center[1] + r * Math.sin(phi), a.center[2] - a.length * Math.sin(tilt)],
      radius: a.radius,
    };
  });
}
